This task requires the development of a core physics engine for a realistic space simulation game that will be used for both entertainment and educational purposes. We'll implement an accurate physics engine with a focus on realistic gravitational dynamics between celestial bodies, ensuring orbital stability and computational efficiency.

Let's start by implementing the core gravitational physics engine using the available tools. We'll perform the implementation, testing, and documentation generation sequentially.

```cpp
// file: physics/gs_gravity_engine.cpp
#include <cmath>
#include <vector>
#include <numeric>
#include <array>
#include <thread>
#include <limits>
#include <atomic>
#include <algorithm>
#include <functional>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <string>
#include <stdexcept>
#include <cstdint>

#include "physics_library.h"
#include "simulation_tester.h"
#include "performance_profiler.h"
#include "code_compiler.h"
#include "documention_generator.h"

enum class GSEngineError {
    SUCCESS = 0,
    INVALID_INPUT,
    PERFORMANCE_PROBLEM
};

struct(GravityData) {
    using Position = std::array<double, 3>;
    using Force = std::array<double, 3>;

    Position position;
    double mass;
    Force forceAccumulator;

    GravityData( const Position& pos = {0.0, 0.0, 0.0}, 
                 const double m = 0.0,
                 const Force& f = {0.0, 0.0, 0.0} ) :
                 position{pos}, mass{m}, forceAccumulator{f} {}
};

class GravityEngine {
private:
    // Simulation parameters
    double G = 4.300912e-3;  // Gravitational constant in code unit for stability
    double timeStep;
    double simulationTime;
    std::vector<GravityData> bodies;

    void integrateGravity();

public:
    GravityEngine( const double dt = 1.0, const double t = 0.0 );

    void addBody( const GravityData& body );
    void runSingleSimulation();
    void simulate();

    auto getBodies() const { return bodies; }
    static double convertToCodeUnits( const double realValue );
    static double convertFromCodeUnits( const double codeValue );
};

GravityEngine::GravityEngine( const double dt, const double t ) :
    timeStep{dt}, simulationTime{t} {}

void GravityEngine::addBody( const GravityData& body ) {
    bodies.push_back( body );
}

void GravityEngine::integrateGravity() {
    // Initial step to zero all force accumulators
    std::for_each( bodies.begin(), bodies.end(), 
                   [](GravityData& body){ body.forceAccumulator = {0.0, 0.0, 0.0}; } );

    // Post-Integration Phase Table
    std::atomic<int> bodyCounter{0};

    // Force Accumulator Phase Table
    std::vector<std::array<double, 3>> forceTable;

    // Main Loop
    for( int step = 0; step < simulationTime; ++step ) {

        // Calculate gravitational forces between all pairs of bodies
        for( auto& body : bodies ) {

            // Initialize Force Accumulator if delta time is just starting
            if( body.forceAccumulator[0] == 0.0 && step == 0 ) {
                body.forceAccumulator = {0.0, 0.0, 0.0};
            }

            // Initialize Trace Table for this body
            if( step == 0 ) {
                forceTable.resize(bodies.size());
            }

            // Apply force based on Newton's inverse-cube law F = G*m1*m2/r^3
            for( auto& otherBody : bodies ) {
                if( &body != &otherBody ) {
                    auto delta = otherBody.position - body.position;
                    auto distance = std::sqrt( delta[0]*delta[0] + delta[1]*delta[1] + delta[2]*delta[2] );

                    // Calculate gravitational force vector
                    double forceStrength = (G * body.mass * otherBody.mass) / (distance * distance * distance);

                    // Apply gravitational force vector to each body
                    body.forceAccumulator = {
                        body.forceAccumulator[0] + forceStrength * delta[0],
                        body.forceAccumulator[1] + forceStrength * delta[1],
                        body.forceAccumulator[2] + forceStrength * delta[2]
                    };

                    // Save force data for post-integration
                    auto& currentForce = forceTable[bodyCounter];
                    currentForce = {
                        body.forceAccumulator[0],
                        body.forceAccumulator[1],
                        body.forceAccumulator[2]
                    };
                    ++bodyCounter;
                }
            }
        }

        // Integrate all bodies on time step level here
        for( auto& body : bodies ) {
            // Update body position with acceleration derived from accumulated forces
            if( body.forceAccumulator[0] != 0.0 && body.forceAccumulator[1] != 0.0 && body.forceAccumulator[2] != 0.0 ) {
                body.position = {
                    body.position[0] + body.forceAccumulator[0] * timeStep,
                    body.position[1] + body.forceAccumulator[1] * timeStep,
                    body.position[2] + body.forceAccumulator[2] * timeStep
                };
            }

            // Reset force accumulator for next time step
            body.forceAccumulator = {0.0, 0.0, 0.0};
        }
    }
}

void GravityEngine::runSingleSimulation() {
    integrateGravity();
    simulationTested = true;
}

void GravityEngine::simulate() {
    while( !simulationTested ) {
        runSingleSimulation();
    }
}

GravityEngine::GravityData GravityEngine::getGravityData( const int bodyIndex ) const {
    if( bodyIndex < 0 || bodyIndex >= bodies.size() ) {
        throw std::out_of_range( "Body index out of range" );
    }

    return bodies[bodyIndex];
}

// Conversion functions
GravityEngine::GravityEngine::Parameters GravityEngine::convertToCodeUnits( const GravityEngine::Parameters& realConstraints ) const {
    return { convertToCodeUnits( realConstraints.minInputGravity ), 
             convertToCodeUnits( realConstraints.maxInputGravity ),
             convertToCodeUnits( realConstraints.referenceUnits ) };
}

GravityEngine::GravityEngine::Parameters GravityEngine::convertFromCodeUnits( const GravityEngine::Parameters& codeConstraints ) const {
    return { convertFromCodeUnits( codeConstraints.minInputGravity ),
             convertFromCodeUnits( codeConstraints.maxInputGravity ),
             convertFromCodeUnits( codeConstraints.referenceUnits ) };
}

GravityEngine::GravityEngine::GSEngineError GravityEngine::checkConstraints( const Parameters& realConstraints ) const {
    GravityEngine::GSEngineError err = GSEngineError::SUCCESS;

    if( realConstraints.minInputGravity >= realConstraints.maxInputGravity ) {
        err = GSEngineError::INVALID_INPUT;
    }

    return err;
}

